CREATE POLICY "platform_media_owner_read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'platform-media' AND public.is_platform_owner(auth.uid()));
CREATE POLICY "platform_media_owner_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'platform-media' AND public.is_platform_owner(auth.uid()));
CREATE POLICY "platform_media_owner_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'platform-media' AND public.is_platform_owner(auth.uid())) WITH CHECK (bucket_id = 'platform-media' AND public.is_platform_owner(auth.uid()));
CREATE POLICY "platform_media_owner_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'platform-media' AND public.is_platform_owner(auth.uid()));